<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('video_categories.manage');
if(is_post()){verify_csrf();$action=(string)input('action');try{$pdo=db();$pdo->beginTransaction();if($action==='category'){$name=trim((string)input('name'));if($name===''||strlen($name)>190)throw new InvalidArgumentException('Category name is required.');$slug='cat_'.preg_replace('/[^a-z0-9]+/','_',strtolower($name));$slug=trim($slug,'_');$pdo->prepare('INSERT INTO video_categories(name,slug,status,created_by) VALUES(?,?,"ACTIVE",?)')->execute([$name,$slug,admin()['id']]);$record=(string)$pdo->lastInsertId();}elseif($action==='video'){$url=youtube_embed_url((string)input('video_url'));$pdo->prepare('INSERT INTO hunt_videos(hunt_id,location_id,category_id,title,video_url,clue_text,sort_order,status) VALUES(?,?,?,?,?,?,?,"ACTIVE")')->execute([(int)input('hunt_id'),(int)input('location_id')?:null,(int)input('category_id')?:null,trim((string)input('title')),$url,trim((string)input('clue_text')),(int)input('sort_order')]);$record=(string)$pdo->lastInsertId();}elseif($action==='ad'){$type=strtoupper((string)input('display_type'));$media=trim((string)input('media_url'));if(!in_array($type,['PRE_ROLL','MID_ROLL','FULL_SCREEN'],true)||!filter_var($media,FILTER_VALIDATE_URL)||($type==='MID_ROLL'&&!filter_var(input('trigger_seconds'),FILTER_VALIDATE_INT)) )throw new InvalidArgumentException('Valid ad type, media URL, and mid-roll trigger are required.');$cta=trim((string)input('cta_url'));if($cta!==''&&!filter_var($cta,FILTER_VALIDATE_URL))throw new InvalidArgumentException('CTA URL is invalid.');$pdo->prepare('INSERT INTO video_ads(video_id,enabled,display_type,trigger_seconds,media_url,skip_after_seconds,cta_text,cta_url,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([(int)input('video_id'),filter_var(input('enabled'),FILTER_VALIDATE_BOOL)?1:0,$type,$type==='MID_ROLL'?(int)input('trigger_seconds'):null,$media,trim((string)input('skip_after_seconds'))!==''?(int)input('skip_after_seconds'):null,trim((string)input('cta_text'))?:null,$cta?:null,admin()['id']]);$record=(string)$pdo->lastInsertId();}elseif($action==='toggle'){$table=(string)input('table');if(!in_array($table,['video_categories','hunt_videos','video_ads'],true))throw new InvalidArgumentException('Invalid video component.');$pdo->prepare("UPDATE {$table} SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE id=?")->execute([(int)input('id')]);$record=(string)(int)input('id');}else throw new InvalidArgumentException('Invalid action.');audit_log((int)admin()['id'],'VIDEO_'.strtoupper($action),'video',$record??null);$pdo->commit();flash('success','Video configuration saved.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('/admin/video/index.php');}
$categories=db()->query('SELECT * FROM video_categories ORDER BY name')->fetchAll();$hunts=db()->query('SELECT id,title FROM hunts ORDER BY title')->fetchAll();$videos=db()->query('SELECT v.*,h.title hunt,c.name category FROM hunt_videos v JOIN hunts h ON h.id=v.hunt_id LEFT JOIN video_categories c ON c.id=v.category_id ORDER BY v.id DESC LIMIT 300')->fetchAll();$ads=db()->query('SELECT a.*,v.title video FROM video_ads a JOIN hunt_videos v ON v.id=a.video_id ORDER BY a.id DESC')->fetchAll();$pageTitle='Video categories & ads';$pageSubtitle='Dynamic categories, clean YouTube embeds, clue text, spot links, and sponsor flows';require APP_ROOT.'/includes/header.php';?>
<div class="grid detail-grid"><section class="panel"><h2>Create category</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="category"><input name="name" maxlength="190" placeholder="Shopping Mall Clues" required><button class="btn">Create category</button></form><div class="table-wrap"><table><thead><tr><th>Category</th><th>Slug</th><th>Status</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=e($c['status'])?></td></tr><?php endforeach?></tbody></table></div></section><section class="panel"><h2>Add clue video</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="video"><input name="title" placeholder="Video title" required><select name="hunt_id" required><option value="">Hunt</option><?php foreach($hunts as $h):?><option value="<?=e($h['id'])?>"><?=e($h['title'])?></option><?php endforeach?></select><select name="category_id"><option value="">Category</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach?></select><input type="url" name="video_url" placeholder="Unlisted YouTube URL" required><textarea name="clue_text" placeholder="Bilingual clue/instructions"></textarea><input type="number" name="location_id" min="1" placeholder="Optional QR spot ID"><input type="number" name="sort_order" min="0" value="0"><button class="btn">Save video</button></form></section></div>
<section class="panel"><h2>Video library</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Hunt</th><th>Category</th><th>Embed</th><th>Clue</th><th>Status</th></tr></thead><tbody><?php foreach($videos as $v):?><tr><td><?=e($v['title'])?></td><td><?=e($v['hunt'])?></td><td><?=e($v['category']??'—')?></td><td><a href="<?=e($v['video_url'])?>" target="_blank" rel="noopener">Preview</a></td><td><?=e(mb_strimwidth((string)$v['clue_text'],0,80,'…'))?></td><td><?=e($v['status'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="panel"><h2>Advertisement engine</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="ad"><div class="field"><label>Video</label><select name="video_id" required><?php foreach($videos as $v):?><option value="<?=e($v['id'])?>"><?=e($v['title'])?></option><?php endforeach?></select></div><div class="field"><label>Display type</label><select name="display_type"><option>PRE_ROLL</option><option>MID_ROLL</option><option>FULL_SCREEN</option></select></div><div class="field"><label>Mid-roll trigger seconds</label><input type="number" name="trigger_seconds" min="1"></div><div class="field"><label>Ad media URL</label><input type="url" name="media_url" required></div><div class="field"><label>Skip after seconds</label><input type="number" name="skip_after_seconds" min="0" placeholder="Blank = non-skippable"></div><div class="field"><label>CTA text</label><input name="cta_text" placeholder="Visit Sponsor"></div><div class="field"><label>CTA URL</label><input type="url" name="cta_url"></div><div class="field"><label><input type="checkbox" name="enabled" value="1" checked> Enabled</label></div><div class="field full"><button class="btn">Save advertisement</button></div></form><div class="table-wrap"><table><thead><tr><th>Video</th><th>Type</th><th>Trigger</th><th>Skip</th><th>CTA</th><th>Status</th></tr></thead><tbody><?php foreach($ads as $a):?><tr><td><?=e($a['video'])?></td><td><?=e($a['display_type'])?></td><td><?=e($a['trigger_seconds']??'—')?> sec</td><td><?=e($a['skip_after_seconds']??'No skip')?></td><td><?=e($a['cta_text']??'—')?></td><td><?=e($a['enabled']?'ON':'OFF')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
